		const request =
			options === undefined
				? adapter.createWorkout({ workout: input.workout })
				: adapter.createWorkout({ workout: input.workout }, options);
		return yield* request;
	});

	const operation: WorkoutsCreateOperation = {
		descriptor: workoutsCreateDescriptor,
