			Effect.catchIf(
				(error) =>
					isExpectedReadEndOfList(error, "/v1/workouts/events", input.page),
				() =>
					Effect.succeed({
						events: [],
						page: input.page,
						pageCount: undefined,
						since: input.since,
						expected404Outcome: "end_of_list" as const,
