function normalizeRoutineResponse(
	response: PostV1Routines201 | PutV1RoutinesRoutineid200,
): Routine | undefined {
	if (Predicate.isObject(response) && Object.keys(response).length === 0) {
		return undefined;
	}
	return response as Routine;
