import { Effect } from "effect";
import type {
	HevyExecutionOptions,
	HevyOperationSafety,
} from "@hevy-mcp/hevy-client";
import type {
	HevyRequestEffectClient,
	HevyRequestEffectError,
} from "@hevy-mcp/hevy-client/internal";
import type {
	BodyMeasurement,
	GetV1BodyMeasurements200,
} from "@hevy-mcp/hevy-client/types";
import {
	isExpectedReadEndOfList,
	PaginationMismatchError,
} from "./operation-errors.js";

export interface BodyMeasurementsListInput {
	readonly page: number;
	readonly pageSize: number;
}

export interface BodyMeasurementsListOutput {
	readonly items: BodyMeasurement[];
	readonly page: number;
	readonly pageCount?: number;
	readonly expected404Outcome?: "end_of_list";
}

export type BodyMeasurementsListAdapter = Pick<
	HevyRequestEffectClient,
	"getBodyMeasurements"
>;

export interface BodyMeasurementsListDescriptor {
	readonly id: "bodyMeasurements.list";
	readonly safety: Extract<HevyOperationSafety, "read">;
}

export const bodyMeasurementsListDescriptor: BodyMeasurementsListDescriptor = {
	id: "bodyMeasurements.list",
	safety: "read",
};

export interface BodyMeasurementsListOperation {
	readonly descriptor: BodyMeasurementsListDescriptor;
	readonly effect: (
		input: BodyMeasurementsListInput,
		options?: HevyExecutionOptions,
	) => Effect.Effect<
		BodyMeasurementsListOutput,
		HevyRequestEffectError | PaginationMismatchError
	>;
	execute(
		input: BodyMeasurementsListInput,
		options?: HevyExecutionOptions,
	): Promise<BodyMeasurementsListOutput>;
}

export function createBodyMeasurementsListOperation(
	adapter: BodyMeasurementsListAdapter,
): BodyMeasurementsListOperation {
	const effect = Effect.fn("operations.bodyMeasurements.list")(function* (
		input: BodyMeasurementsListInput,
		options?: HevyExecutionOptions,
	) {
		const params = { page: input.page, pageSize: input.pageSize };
		const request =
			options === undefined
				? adapter.getBodyMeasurements(params)
				: adapter.getBodyMeasurements(params, options);
		return yield* request.pipe(
			Effect.flatMap((response: GetV1BodyMeasurements200) => {
				if (response?.page !== undefined && response.page !== input.page) {
					return Effect.fail(
						new PaginationMismatchError({
							requested: input.page,
							received: response.page,
							collection: "bodyMeasurements",
							message: `Body measurements page mismatch: requested page ${input.page} but received page ${response.page}`,
						}),
					);
				}
				return Effect.succeed({
					items: response?.body_measurements ?? [],
					page: response?.page ?? input.page,
					pageCount: response?.page_count,
				});
			}),
			Effect.catchIf(
				(error) =>
					isExpectedReadEndOfList(error, "/v1/body_measurements", input.page),
				() =>
					Effect.succeed({
						items: [],
						page: input.page,
						pageCount: undefined,
						expected404Outcome: "end_of_list" as const,
					}),
			),
		);
	});

	const operation: BodyMeasurementsListOperation = {
		descriptor: bodyMeasurementsListDescriptor,
		effect,
		execute(input, options) {
			return Effect.runPromise(operation.effect(input, options));
		},
	};
	return operation;
}

import { NotFoundError } from "@hevy-mcp/hevy-client";
import type { GetV1BodyMeasurements200 } from "@hevy-mcp/hevy-client/types";
import { Effect } from "effect";
import { describe, expect, it } from "vitest";
import {
	createBodyMeasurementsListOperation,
	type BodyMeasurementsListAdapter,
} from "./body-measurements.js";

function notFound(endpoint = "/v1/body_measurements") {
	return new NotFoundError({
		status: 404,
		method: "GET",
		endpoint,
		expected: true,
	});
}

function createAdapter(
	responses: readonly (GetV1BodyMeasurements200 | Error)[],
) {
	let responseIndex = 0;
	const requests: Array<{
		readonly params: Parameters<
			BodyMeasurementsListAdapter["getBodyMeasurements"]
		>[0];
		readonly options: Parameters<
			BodyMeasurementsListAdapter["getBodyMeasurements"]
		>[1];
	}> = [];
	const argumentCounts: number[] = [];
	const adapter: BodyMeasurementsListAdapter = {
		getBodyMeasurements(params, options) {
			argumentCounts.push(arguments.length);
			requests.push({ params, options });
			const response = responses[responseIndex++] ?? {
				body_measurements: [],
			};
			return response instanceof Error
				? Effect.fail(response)
				: Effect.succeed(response);
		},
	};
	return { adapter, requests, argumentCounts };
}

describe("bodyMeasurements.list operation", () => {
	it("normalizes the response envelope without changing empty 200 responses", async () => {
		const { adapter, requests } = createAdapter([
			{
				page: 2,
				page_count: 4,
				body_measurements: [],
			},
		]);
		const operation = createBodyMeasurementsListOperation(adapter);
		const options = { timeoutMs: 1_000 };

		await expect(
			Effect.runPromise(operation.effect({ page: 2, pageSize: 10 }, options)),
		).resolves.toEqual({
			items: [],
			page: 2,
			pageCount: 4,
		});
		expect(requests).toEqual([{ params: { page: 2, pageSize: 10 }, options }]);
	});

	it("defaults omitted page and body_measurements fields", async () => {
		const { adapter } = createAdapter([{}]);
		const operation = createBodyMeasurementsListOperation(adapter);

		await expect(
			Effect.runPromise(operation.effect({ page: 3, pageSize: 10 })),
		).resolves.toEqual({
			items: [],
			page: 3,
			pageCount: undefined,
		});
	});

	it("recovers only a later-page tagged collection 404", async () => {
		const operation = createBodyMeasurementsListOperation(
			createAdapter([notFound()]).adapter,
		);

		await expect(
			Effect.runPromise(operation.effect({ page: 2, pageSize: 10 })),
		).resolves.toEqual({
			items: [],
			page: 2,
			pageCount: undefined,
			expected404Outcome: "end_of_list",
		});

		const firstPageOperation = createBodyMeasurementsListOperation(
			createAdapter([notFound()]).adapter,
		);
		await expect(
			Effect.runPromise(firstPageOperation.effect({ page: 1, pageSize: 10 })),
		).rejects.toBeInstanceOf(NotFoundError);
	});

	it("fails page mismatches as a tagged domain error", async () => {
		const operation = createBodyMeasurementsListOperation(
			createAdapter([
				{
					page: 3,
					page_count: 4,
					body_measurements: [],
				},
			]).adapter,
		);

		await expect(
			Effect.runPromise(operation.effect({ page: 2, pageSize: 10 })),
		).rejects.toMatchObject({
			_tag: "PaginationMismatchError",
			requested: 2,
			received: 3,
			collection: "bodyMeasurements",
		});
	});
});

import { HevyHttpError, NotFoundError } from "@hevy-mcp/hevy-client";
import { describe, expect, it } from "vitest";
import {
	classifyReadError,
	isExpectedReadEndOfList,
	isExpectedReadNotFound,
} from "./operation-errors.js";

function notFound(endpoint: string, method = "GET") {
	return new HevyHttpError("not found", {
		status: 404,
		method,
		endpoint,
	});
}

describe("classifyReadError", () => {
	it("classifies a known resource 404", () => {
		const error = notFound("/v1/routines/routine-1");

		expect(classifyReadError(error, "/v1/routines")).toBe("not_found");
		expect(isExpectedReadNotFound(error, "/v1/routines")).toBe(true);
	});

	it("classifies a later collection-page 404", () => {
		const error = notFound("/v1/workouts");

		expect(classifyReadError(error, "/v1/workouts", 2)).toBe("end_of_list");
		expect(isExpectedReadEndOfList(error, "/v1/workouts", 2)).toBe(true);
	});

	it("does not hide first-page, mutation, or unrelated 404s", () => {
		expect(
			classifyReadError(notFound("/v1/workouts"), "/v1/workouts", 1),
		).toBeUndefined();
		expect(
			classifyReadError(notFound("/v1/workouts", "POST"), "/v1/workouts", 2),
		).toBeUndefined();
		expect(
			classifyReadError(notFound("/v1/routines/routine-1"), "/v1/workouts", 2),
		).toBeUndefined();
		expect(
			classifyReadError(new Error("network failure"), "/v1/workouts", 2),
		).toBeUndefined();
	});

	it("classifies tagged collection 404s only for their matching endpoint", () => {
		const endpoints = [
			"/v1/body_measurements",
			"/v1/exercise_templates",
			"/v1/routine_folders",
			"/v1/routines",
			"/v1/workouts",
			"/v1/workouts/events",
		] as const;

		for (const endpoint of endpoints) {
			const error = new NotFoundError({
				status: 404,
				method: "GET",
				endpoint,
				expected: true,
			});

			expect(classifyReadError(error, endpoint, 2)).toBe("end_of_list");
			expect(classifyReadError(error, endpoint, 1)).toBeUndefined();
		}
	});

	it("does not classify a sibling endpoint through a collection prefix", () => {
		const error = new NotFoundError({
			status: 404,
			method: "GET",
			endpoint: "/v1/workouts/count",
			expected: true,
		});

		expect(classifyReadError(error, "/v1/workouts", 2)).toBeUndefined();
	});

	it("does not classify history, count, or user 404s as expected reads", () => {
		for (const endpoint of [
			"/v1/exercise_history/:exerciseTemplateId",
			"/v1/workouts/count",
			"/v1/user/info",
		] as const) {
			const error = new NotFoundError({
				status: 404,
				method: "GET",
				endpoint,
				expected: false,
			});

			expect(classifyReadError(error, endpoint)).toBeUndefined();
			expect(classifyReadError(error, endpoint, 2)).toBeUndefined();
		}
	});
});

